<section id="orders-catalog-panel" hidden aria-labelledby="orders-catalog-title">
    <div id="oc-list">
        <div class="section-heading"><div><h2 id="orders-catalog-title">Catálogo y existencias</h2><p>Productos y precios actuales del POS. Consulta todas las ubicaciones y prepara los traspasos necesarios.</p></div><button id="oc-refresh" type="button" class="secondary">Actualizar catálogo</button></div>
        <form id="oc-filters" class="filters"><div><label for="oc-search">Buscar producto, variante o SKU</label><input id="oc-search" type="search"></div><div><label for="oc-category">Categoría</label><select id="oc-category"><option value="">Todas las categorías</option></select></div><div><label for="oc-location">Existencias en</label><select id="oc-location"><option value="">Todas las ubicaciones</option></select></div></form>
        <p id="oc-updated" class="hint" role="status"></p><div id="oc-grid" class="orders-live-grid"></div><p id="oc-empty" hidden>No hay productos con esos filtros.</p>
    </div>
    <section id="oc-detail" hidden aria-labelledby="oc-title">
        <div class="section-heading"><h2 id="oc-title"></h2><button id="oc-back" type="button" class="secondary">Volver al catálogo</button></div>
        <div class="orders-live-detail"><div><img id="oc-photo" class="orders-live-photo" alt="" hidden><div id="oc-no-photo" class="orders-live-no-photo">Sin imágenes</div><div id="oc-thumbs" class="orders-live-thumbs"></div></div><div><p id="oc-summary"></p><p id="oc-price" class="orders-live-price"></p><p id="oc-description"></p><dl id="oc-specs"></dl><button id="oc-detail-add" class="primary" type="button">Agregar al pedido</button><p class="hint">El precio incluye los impuestos del producto. Un traspaso mueve existencias; no registra una venta ni cambia el precio.</p></div></div>
        <h3>Existencias por ubicación</h3><div class="table-scroll"><table><thead><tr><th>Ubicación</th><th>Uso</th><th>Existencia</th><th>Acción</th></tr></thead><tbody id="oc-stock"></tbody></table></div>
    </section>
    <section id="oc-order" class="catalog-editor" hidden aria-labelledby="oc-order-title">
        <div class="section-heading"><div><h2 id="oc-order-title">Armar pedido</h2><p>Selecciona productos, revisa las cantidades y captura los datos del cliente.</p></div><button id="oc-order-clear" class="secondary" type="button">Vaciar pedido</button></div>
        <form id="oc-order-form"><fieldset id="oc-order-fields" class="adjust-fields"><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio estimado</th><th>Importe</th><th>Acción</th></tr></thead><tbody id="oc-order-lines"></tbody></table></div><p id="oc-order-total" class="order-total"></p><div class="filters"><div><label for="oc-order-name">Nombre del cliente</label><input id="oc-order-name" maxlength="120" autocomplete="off" required></div><div><label for="oc-order-phone">Celular del cliente</label><input id="oc-order-phone" type="tel" inputmode="tel" maxlength="30" autocomplete="off" placeholder="10 dígitos o código de país" required></div></div><label for="oc-order-notes">Notas del pedido (opcional)</label><textarea id="oc-order-notes" maxlength="500" rows="2"></textarea></fieldset><p class="hint">Guardar no reserva existencias ni registra cobros. El precio y la disponibilidad se revisan al pasar a venta. Los artículos por cotizar necesitan un precio acordado antes de venderse.</p><p id="oc-order-message" role="status" aria-live="polite"></p><div class="form-actions"><button id="oc-order-save" class="primary" type="submit">Guardar pedido</button></div></form>
    </section>
    <button id="oc-order-summary" class="primary orders-draft-bar" type="button" hidden>Revisar pedido</button>
    <section id="oc-transfer" class="catalog-editor" hidden aria-labelledby="oc-transfer-title">
        <h2 id="oc-transfer-title">Traspasar mercancía</h2><p id="oc-transfer-product"></p>
        <form id="oc-transfer-form"><fieldset id="oc-transfer-fields" class="adjust-fields"><div class="filters"><div><label for="oc-origin">Ubicación de origen</label><select id="oc-origin" required></select></div><div><label for="oc-destination">Ubicación de destino</label><select id="oc-destination" required></select></div><div><label for="oc-quantity">Cantidad a traspasar</label><input id="oc-quantity" type="number" min="1" step="1" required></div></div><p id="oc-transfer-preview" class="hint"></p><label for="oc-reason">Motivo del traspaso</label><textarea id="oc-reason" rows="2" maxlength="300" required></textarea><label class="check-label"><input id="oc-confirm" type="checkbox" required>Confirmo que la mercancía ya se entregó a la ubicación de destino.</label></fieldset><p id="oc-transfer-message" role="status" aria-live="polite"></p><div class="form-actions"><button id="oc-transfer-save" type="submit" class="primary">Confirmar traspaso</button><button id="oc-transfer-cancel" type="button" class="secondary">Volver al producto</button></div></form>
    </section>
</section>
